# <<< SPEC

# >>> HINTS
# <<< HINTS

# >>> STATIC
_static_approval_mode() {
    cat <<-'ARGCEOF'
	plan	Analyze only, do not modify files or execute commands
	default	Require approval for file edits or shell commands
	auto-edit	Automatically approve file edits
	auto	LLM classifier auto-approves safe actions, blocks risky ones
	yolo	Automatically approve all tools
ARGCEOF
}
# <<< STATIC

# >>> CHOICES
if [[ -n "$ARGC_COMPLETIONS_ROOT" && -f "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh" ]]; then
    . "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh"
fi

_choice_batch_task() {
    qwen batch list 2>/dev/null | gawk -F'\t' 'NF > 1 { print $1 "\t" $2 }'
}

_choice_extension_source() {
    qwen extensions sources list 2>/dev/null | _argc_util_strip_ansi | gawk '
        /^[[:space:]]*$/ {
            if (name != "" && body) print name
            name = ""
            body = 0
            next
        }
        name == "" { name = $0; next }
        /^[[:space:]]/ { body = 1 }
        END { if (name != "" && body) print name }'
}

_choice_qwen_controller_id() {
    qwen sessions controllers list --json 2>/dev/null \
        | jq -b -r 'select(.id) | "\(.id)\t\((.label // "") | gsub("[\r\n\t]+"; " "))"'
}

_choice_qwen_extension() {
    _argc_util_cache 60 _choice_qwen_extension_uncached qwen_extension
}

_choice_qwen_extension_uncached() {
    qwen extensions list 2>/dev/null | _argc_util_strip_ansi | gawk '
        /^[^[:space:]]+ .* \([^()]*\)$/ {
            line = $0
            sub(/^[^[:space:]]+ /, "", line)
            sub(/ \([^()]*\)$/, "", line)
            print line
        }'
}

_choice_qwen_mcp_server() {
    _argc_util_cache 120 _choice_qwen_mcp_server_uncached qwen_mcp_server
}

_choice_qwen_mcp_server_uncached() {
    qwen mcp list 2>/dev/null | _argc_util_strip_ansi | sed -n 's/^[^ ]* \([^:]*\): .*/\1/p'
}

_choice_qwen_session_id() {
    qwen sessions list --json --limit 100 2>/dev/null \
        | jq -b -r 'select(.sessionId) | "\(.sessionId)\t\((.customTitle // .prompt // "") | gsub("[\r\n\t]+"; " "))"'
}
# <<< CHOICES

command eval "$(argc --argc-eval "$0" "$@")"
